  assert.match(posted[0].body, /^<!-- speckit-implement:blocked \{"pull":12,"stage":"implement"\} -->\n\*\*Blocked\*\* by spec #12 \(spec twin #30\)[\s\S]*- \*\*Unblocks by itself\*\* once #30 is implemented/);
  await setAttention(github, 9, true);
